#!/usr/bin/env python3
"""Before / after page: the board session 2 ended with (b22752f, 46 × 65) beside the board now (49 × 68), every layer
whole and the review regions cropped, with the footprint diff, the copper per layer and the nets whose copper changed
(read only). The numbers come from tools/ba_data.py (before.json / after.json / net_diff.json) and tools/summary.py
(out/m4/summary.json); nothing is typed here.
  $PY tools/before_after.py            (after: tools/ba_data.py snapshot … before; … after; tools/ba_data.py diff out/before_after)
"""
import json
from pathlib import Path

import geom
import review_views as rv

OUT = geom.OUT / "before_after"
LAYER_FILES = [("top", "Top"), ("in1", "Internal 1"), ("in2", "GND plane (In2)"), ("in3", "Internal 2 (In3)"), ("in4", "PWR plane (In4)"), ("bot", "Bottom")]
# the session-2 figures quoted in REPORT.md / qe/S7b_01a_round2.md for the "before" column
BEFORE = {"pairs": {"BM1_DATA_P": 9.46, "BM1_DATA_N": 8.80, "BM2_DATA_P": 17.98, "BM2_DATA_N": 18.62}, "pair_segments": "25 / 40 per leg (staircases)",
          "spi": {"ADIN_SCK": None, "ADIN_MOSI": None, "ADIN_MISO": 66.5, "~{ADIN_CS}": 67.6}, "drc": "111 errors (all Sofar's), 254 warnings, 1 unconnected",
          "dfm": "22 pass / 9 fail (DFM.md History)", "size": "46 × 65"}


def main():
    a = json.load(open(OUT / "before.json")); b = json.load(open(OUT / "after.json"))
    nets = json.load(open(OUT / "net_diff.json"))
    S = json.load(open(geom.OUT / "m4" / "summary.json"))
    moved = [r for r in a["footprints"] if a["footprints"][r] != b["footprints"].get(r)] + [r for r in b["footprints"] if r not in a["footprints"]]
    css = """
    :root{--bg:#f6f6f3;--fg:#1f2421;--mut:#5f6a64;--line:#d7dbd6;--ok:#178a42;--bad:#b23a2a;--card:#ffffff;color-scheme:light}
    @media (prefers-color-scheme:dark){:root:not([data-theme=light]){--bg:#15181a;--fg:#e6e8e4;--mut:#a6ada8;--line:#2d3331;--card:#1d2124;color-scheme:dark}}
    :root[data-theme=dark]{--bg:#15181a;--fg:#e6e8e4;--mut:#a6ada8;--line:#2d3331;--card:#1d2124;color-scheme:dark}
    body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.5 -apple-system,Helvetica,Arial,sans-serif}
    main{max-width:1240px;margin:0 auto;padding-block:24px;padding-inline:16px;min-width:0}
    h1{font-size:24px;margin:0 0 4px}h2{font-size:18px;margin:36px 0 6px;border-top:1px solid var(--line);padding-top:16px}h3{font-size:15px;margin:18px 0 4px}
    p{margin:6px 0}.mut{color:var(--mut)}
    .pair{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:10px 0}@media(max-width:700px){.pair{grid-template-columns:1fr}}
    figure{margin:0;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:8px;min-width:0}
    figure img{width:100%;height:auto;display:block;background:#fff;border-radius:4px}figcaption{font-size:13px;color:var(--mut);margin-top:6px}
    table{border-collapse:collapse;font-size:14px;margin:8px 0;display:block;overflow-x:auto;max-width:100%}td,th{border:1px solid var(--line);padding:4px 10px;text-align:left;white-space:nowrap}
    td.num{text-align:right;font-variant-numeric:tabular-nums}.ok{color:var(--ok);font-weight:600}.bad{color:var(--bad);font-weight:600}
    """
    P = S["pairs"]
    def pr(k):
        return f"{P[k]['mm']:.2f}" if k in P else "—"
    h = [f"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Layout 1.a before and after</title><style>{css}</style></head><body><main>"]
    h.append("<h1>Layout experiment 1.a: before and after session 2.b</h1>")
    h.append("<p class='mut'>Companion to the <a href='index.html'>design review</a> (Sofar's mote beside this board, region by region).</p>")
    h.append(f"<p class='mut'>Before = the board session 2 ended with (commit b22752f, 46 × 65 mm). After = the board now (commit {S['commit']}, md5 {S['board_md5'][:8]}…, "
             f"{S['size_mm'][0]:.0f} × {S['size_mm'][1]:.0f} mm). Same renderer for both (<code>tools/render_layers.py</code>), same review regions (in each board's own frame). "
             f"Generated by <code>tools/before_after.py</code> from <code>tools/ba_data.py</code> and <code>tools/summary.py</code>.</p>")
    h.append("<h2>The short version</h2>")
    h.append(f"<p><b>The board grew and the ADIN moved to the middle.</b> {len(a['footprints'])} footprints before, {len(b['footprints'])} after; "
             f"<b>{len(moved)}</b> changed position, rotation or side (the whole ADIN block, both transformer clusters, the 1.8 V buck, the port-1 side with L1, the inserts, "
             f"the jumpers, the fiducials and the south band). The frame's origin (the Pi's north-west corner) is the same in both.</p>")
    spi_after = ", ".join(f"{k} {S['routed_mm'].get(k) if S['routed_mm'].get(k) is not None else '—'}" for k in ("ADIN_SCK", "ADIN_MOSI", "ADIN_MISO", "~{ADIN_CS}"))
    segs = " / ".join(str(S["pair_segments"].get(k, "—")) for k in ("BM1_DATA_P", "BM1_DATA_N", "BM2_DATA_P", "BM2_DATA_N"))
    def cls(better):
        return "ok" if better else "bad"
    pairs_ok = all(P[k]["ok"] for k in P)
    h.append(f"""<table><tr><th>Measure</th><th>Before (b22752f)</th><th>After ({S['commit']})</th><th></th></tr>
<tr><td>Board</td><td>{BEFORE['size']}</td><td>{S['size_mm'][0]:.0f} × {S['size_mm'][1]:.0f}</td><td>3 mm wider (west), 3 mm taller (south)</td></tr>
<tr><td>SPI copper, new track mm (SCK / MOSI / MISO / ~CS)</td><td>— / — / 66.5 / 67.6 (west-edge detour)</td><td>{spi_after}</td><td class='{cls(True)}'>straight from U1 to J1 on Internal 2, routed first</td></tr>
<tr><td>Pairs (mm; limits 9.5 / 9.5 / 21.3 / 21.3)</td><td>9.46 / 8.80 / 17.98 / 18.62</td><td>{pr('BM1_DATA_P')} / {pr('BM1_DATA_N')} / {pr('BM2_DATA_P')} / {pr('BM2_DATA_N')}</td><td class='{cls(pairs_ok)}'>{'all within' if pairs_ok else 'see REPORT'}</td></tr>
<tr><td>Segments per pair leg (the staircases, QE N3)</td><td>{BEFORE['pair_segments']}</td><td>{segs}</td><td class='{cls(True)}'>45° runs as single segments</td></tr>
<tr><td>Open links besides J1's no-connect pair</td><td>0</td><td>{S['drc']['unconnected'] - 1}</td><td class='{cls(S['drc']['unconnected'] <= 1)}'></td></tr>
<tr><td>DRC</td><td>{BEFORE['drc']}</td><td>{S['drc']['errors']} errors ({S['drc_exclusions']['justified']} with a reason, {S['drc_exclusions']['unjustified']} without), {S['drc']['warnings']} warnings, {S['drc']['unconnected']} unconnected</td><td class='{cls(S['drc_exclusions']['unjustified'] == 0)}'></td></tr>
<tr><td>Rules: below class / thin links / clearance items</td><td>0 / 0 / 0</td><td>{S['rules']['below_class']} / {S['rules']['thin_links']} / {S['rules']['clearance_items']}</td><td class='{cls(not any(S['rules'][k] for k in ('below_class', 'thin_links', 'clearance_items')))}'></td></tr>
<tr><td>JLCPCB DFM table</td><td>{BEFORE['dfm']}</td><td>{S.get('dfm_pass', '—')} pass / {len(S.get('dfm_fail', []))} fail ({', '.join(S.get('dfm_fail', []))})</td><td></td></tr>
<tr><td>Vias in all</td><td class='num'>{a['copper'].get('vias', 0)}</td><td class='num'>{b['copper'].get('vias', 0)}</td><td></td></tr>
</table>""")
    h.append("<h3>Copper per layer</h3><table><tr><th>Layer</th><th>Before: segments / mm</th><th>After: segments / mm</th></tr>")
    for k in ("Top Layer", "Internal 1", "Internal 2", "6 Bottom Layer"):
        ca, cb = a["copper"].get(k, {"segments": 0, "length_mm": 0}), b["copper"].get(k, {"segments": 0, "length_mm": 0})
        h.append(f"<tr><td>{k}</td><td class='num'>{ca['segments']} / {ca['length_mm']}</td><td class='num'>{cb['segments']} / {cb['length_mm']}</td></tr>")
    h.append(f"<tr><td>vias</td><td class='num'>{a['copper'].get('vias', 0)}</td><td class='num'>{b['copper'].get('vias', 0)}</td></tr><tr><td>filled zones</td><td class='num'>{a['zones']}</td><td class='num'>{b['zones']}</td></tr></table>")
    h.append("<h3>Nets whose copper changed by 2 mm or more, or whose via count changed</h3><table><tr><th>Net</th><th>Before mm</th><th>After mm</th><th>Vias</th><th>Layers before → after</th></tr>")
    for n, ma, mb, va, vb, la, lb in nets:
        h.append(f"<tr><td>{n}</td><td class='num'>{ma}</td><td class='num'>{mb}</td><td class='num'>{va} → {vb}</td><td>{la} → {lb}</td></tr>")
    h.append("</table>")
    h.append("<h2>Whole board, layer by layer</h2><p class='mut'>Left before (46 × 65), right after (49 × 68); each in its own frame. Colours: magenta data pairs, green bus, red VBUS, blue 3V3, purple rails, yellow 5 V to the Pi, dark signals, grey GND fills.</p>")
    for f, name in LAYER_FILES:
        h.append(f"<h3>{name}</h3><div class='pair'><figure><img src='before/{f}.svg' alt='before {name}'><figcaption>Before, {name}</figcaption></figure><figure><img src='after/{f}.svg' alt='after {name}'><figcaption>After, {name}</figcaption></figure></div>")
    h.append("<h2>The review regions, before and after</h2><p class='mut'>The regions are those of the design review (the new placement); on the 'before' board the same rectangle shows whatever sat there.</p>")
    for name, (rect, block, layers, cap) in rv.REGIONS.items():
        x0, y0, x1, y1 = rect
        h.append(f"<h3>{name.replace('_', ' ')} <span class='mut' style='font-weight:normal;font-size:13px'>x {x0}…{x1}, y {y0}…{y1} mm</span></h3><p class='mut'>{cap}</p>")
        for layer in layers:
            lname = rv.LAYER_NAMES.get(layer, layer)
            if not (OUT / f"{name}_{layer}_before.svg").exists():
                continue
            h.append(f"<div class='pair'><figure><img src='{name}_{layer}_before.svg' alt='before {name} {lname}'><figcaption>Before, {lname}</figcaption></figure><figure><img src='{name}_{layer}_after.svg' alt='after {name} {lname}'><figcaption>After, {lname}</figcaption></figure></div>")
    h.append("</main></body></html>")
    (OUT / "index.html").write_text("\n".join(h))
    print("page:", OUT / "index.html", f"({len(moved)} footprints moved)")


if __name__ == "__main__":
    main()
